INSERT INTO english_synset VALUES ('n#04521172',' Gresham''s_law ',NULL,'bad money drives out good; given 2 coins of equal value in paying debts but unequal intrinsic value the weaker will circulate and the stronger will be hoarded');
INSERT INTO english_synset VALUES ('n#04521390',' Kepler''s_law Kepler''s_law_of_planetary_motion ',NULL,'(astronomy) one of three empirical laws of planetary motion stated by Johannes Kepler');
