INSERT INTO english_synset VALUES ('n#04521786',' Kepler''s_second_law law_of_areas law_of_equal_areas ',NULL,'a law concerning the speed at which planets travel; a line connecting a planet to the sun will sweep out equal areas in equal times; \\\\"Kepler''s second law means that a planet''s orbital speed changes with its distance from the sun\\\\"');
INSERT INTO english_synset VALUES ('n#04522117',' Kepler''s_third_law harmonic_law ',NULL,'a law stating that the ratio of the square of the revolutionary period (in years) to the cube of the orbital axis (in astronomical units) is the same for all planets');
INSERT INTO english_synset VALUES ('n#04522362',' law_of_averages ',NULL,'a law affirming that in the long run probabilities will determine performance');
INSERT INTO english_synset VALUES ('n#04522501',' law_of_constant_proportion law_of_definite_proportions ',NULL,'(chemistry) law stating that every pure substance always contains the same elements combined in the same proportions by weight');
INSERT INTO english_synset VALUES ('n#04522730',' law_of_diminishing_returns ',NULL,'a law affirming that to continue after a certain level of performance has been reached will result in a decline in effectiveness');
INSERT INTO english_synset VALUES ('n#04522931',' law_of_effect ',NULL,'(psychology) the principle that behaviors are selected by their consequences; behavior having good consequences tends to be repeated whereas behavior that leads to bad consequences are not repeated');
INSERT INTO english_synset VALUES ('n#04523188',' law_of_equivalent_proportions law_of_reciprocal_proportions ',NULL,'(chemistry) law stating that the proportions in which two elements separately combine with a third element are also the proportions in which they combine together');
INSERT INTO english_synset VALUES ('n#04523458',' law_of_gravitation Newton''s_law_of_gravitation ',NULL,'(physics) the law that states any two bodies attract each other with a force that is directly proportional to the product of their masses and inversely proportional to the square of the distance between them');
INSERT INTO english_synset VALUES ('n#04523779',' law_of_multiple_proportions Dalton''s_law ',NULL,'(chemistry) law stating that when two elements can combine to form more than one compound the amounts of one of them that combines with a fixed amount of the other will exhibit a simple multiple relation');
