INSERT INTO english_synset VALUES ('n#04524283',' Mendel''s_law ',NULL,'(genetics) one of two principles of heredity formulated by Gregor Mendel on the basis of his experiments with plants; the principles were limited and modified by subsequent genetic research');
INSERT INTO english_synset VALUES ('n#04524567',' law_of_segregation ',NULL,'members of a pair of homologous chromosomes separate during the formation of gametes and are distributed to different gametes so that every gamete receives only one member of the pair');
INSERT INTO english_synset VALUES ('n#04524815',' law_of_independent_assortment ',NULL,'each member of a pair of homologous chromosomes separates independently of the members of other pairs so the results are random');
INSERT INTO english_synset VALUES ('n#04525018',' Newton''s_law_of_motion Newton''s_law law_of_motion ',NULL,'one of three basic laws of classical mechanics');
