INSERT INTO english_synset VALUES ('n#04525851',' Ohm''s_law ',NULL,'electric current is directly proportional to voltage and inversely proportional to resistance; I = E/R');
INSERT INTO english_synset VALUES ('n#04526009',' Pauli_exclusion_principle exclusion_principle ',NULL,'no two electrons or protons or neutrons in a given system can be in states characterized by the same set of quantum numbers');
