INSERT INTO english_synset VALUES ('n#05303065',' transition modulation ',NULL,'a musical passage moving from one key to another');
INSERT INTO english_synset VALUES ('n#05303183',' bombast fustian rant claptrap blah ',NULL,'pompous or pretentious talk or writing');
INSERT INTO english_synset VALUES ('n#05303310',' sesquipedality ',NULL,'using long words');
INSERT INTO english_synset VALUES ('n#05303387',' sensationalism luridness ',NULL,'the journalistic use of subject matter that appeals to vulgar tastes; \\\\"the tabloids relied on sensationalism to maintain their circulation\\\\"');
INSERT INTO english_synset VALUES ('n#05303599',' technobabble ',NULL,'technical jargon from computing and other high-tech subjects');
INSERT INTO english_synset VALUES ('n#05303718',' terseness ',NULL,'a neatly short and concise expressive style');
