INSERT INTO english_synset VALUES ('n#05304498',' verboseness verbosity ',NULL,'an expressive style that uses excessive words');
INSERT INTO english_synset VALUES ('n#05304721',' verbiage ',NULL,'overabundance of words');
INSERT INTO english_synset VALUES ('n#05304798',' prolixity prolixness long-windedness wordiness ',NULL,'boring verboseness');
INSERT INTO english_synset VALUES ('n#05304969',' circumlocution periphrasis ',NULL,'a style that involves indirect ways of expressing things');
INSERT INTO english_synset VALUES ('n#05305100',' turgidity turgidness flatulence ',NULL,'pompously embellished language');
