INSERT INTO english_synset VALUES ('n#05305506',' pleonasm ',NULL,'using more words than necessary; \\\\"a tiny little child\\\\"');
INSERT INTO english_synset VALUES ('n#05305615',' tautology ',NULL,'useless repetition; \\\\"to say that something is `adequate enough'' is a tautology\\\\"');
INSERT INTO english_synset VALUES ('n#05305750',' tautology ',NULL,'(in logic) a statement that is necessarily true; \\\\"the statement `he is brave or he is not brave'' is a tautology\\\\"');
