INSERT INTO english_synset VALUES ('n#05306309',' writing_style literary_genre genre ',NULL,'a style of expressing yourself in writing');
INSERT INTO english_synset VALUES ('n#05306507',' form ',NULL,'an arrangement of the elements in a composition or discourse; \\\\"the essay was in the form of a dialogue\\\\"; \\\\"he first skethes the plot in outline form\\\\"');
