INSERT INTO english_synset VALUES ('n#05314709',' ecphonesis exclamation ',NULL,'an exclamatory rhetorical device; \\\\"O tempore! O mores\\\\"');
INSERT INTO english_synset VALUES ('n#05314834',' emphasis ',NULL,'special and significant stress by means of position or repetition e.g.');
