INSERT INTO english_synset VALUES ('n#05328790',' cry outcry call yell shout vociferation ',NULL,'a loud utterance; often in protest or opposition; \\\\"the speaker was interrupted by loud cries from the rear of the audience\\\\"');
INSERT INTO english_synset VALUES ('n#05329225',' cry yell ',NULL,'a loud utterance of emotion (especially when inarticulate); \\\\"a cry of rage\\\\"; \\\\"a yell of pain\\\\"');
INSERT INTO english_synset VALUES ('n#05329393',' bellow bellowing holla holler hollering hollo holloa roar roaring yowl yowling ',NULL,'a very loud utterance; \\\\"his bellow filled the hallway\\\\"');
INSERT INTO english_synset VALUES ('n#05329592',' catcall ',NULL,'a cry expressing disapproval');
INSERT INTO english_synset VALUES ('n#05329674',' clamor clamoring clamour clamouring hue_and_cry ',NULL,'loud and persistent outcry from many people; \\\\"he ignored the clamor of the crowd\\\\"');
