INSERT INTO english_synset VALUES ('n#05329985',' hoot ',NULL,'a loud raucous cry as of an awl');
INSERT INTO english_synset VALUES ('n#05330067',' hosanna ',NULL,'a cry of praise or adoration (to God)');
INSERT INTO english_synset VALUES ('n#05330158',' scream screaming shriek shrieking screech screeching ',NULL,'sharp piercing cry');
INSERT INTO english_synset VALUES ('n#05330285',' whoop ',NULL,'a loud hooting cry of exultation or excitement');
