INSERT INTO english_synset VALUES ('n#09922161',' ream ',NULL,'a large quantity of written matter; \\\\"he wrote reams and reams\\\\"');
INSERT INTO english_synset VALUES ('n#09922274',' small_fortune ',NULL,'a large sum of money; \\\\"he made a small fortune in the commodities market\\\\"');
INSERT INTO english_synset VALUES ('n#09922407',' supply ',NULL,'an amount of something available for use');
INSERT INTO english_synset VALUES ('n#09922518',' tons dozens heaps lots piles scores stacks loads rafts slews wads oodles gobs scads lashings ',NULL,'a large number or amount; \\\\"made lots of new friends\\\\"');
INSERT INTO english_synset VALUES ('n#09922737',' room way elbow_room ',NULL,'space for movement; \\\\"room to pass\\\\"; \\\\"make way for\\\\": \\\\"hardly enough elbow room to turn around\\\\"');
INSERT INTO english_synset VALUES ('n#09923044',' breathing_room breathing_space ',NULL,'sufficient room for easy breathing or movement: \\\\"moved to the country to find breathing room\\\\"');
INSERT INTO english_synset VALUES ('n#09923216',' headroom headway clearance ',NULL,'vertical space available to allow easy passage under something');
INSERT INTO english_synset VALUES ('n#09923355',' houseroom ',NULL,'space for accommodation in a house; \\\\"I wouldn''t give that table houseroom\\\\"');
INSERT INTO english_synset VALUES ('n#09923485',' living_space lebensraum ',NULL,'space sought for occupation by a nation whose population is expanding');
INSERT INTO english_synset VALUES ('n#09923626',' parking ',NULL,'space in which a vehicle can be parked; \\\\"there is plenty of parking behind the store\\\\"');
INSERT INTO english_synset VALUES ('n#09923765',' sea_room ',NULL,'space for maneuver at sea');
INSERT INTO english_synset VALUES ('n#09923845',' swath ',NULL,'the space created by the swing of a scythe or the cut of a mowing machine');
INSERT INTO english_synset VALUES ('n#09923970',' volume ',NULL,'the amount of 3-dimensional space occupied by an object; \\\\"the gas expanded to twice its original volume\\\\"');
INSERT INTO english_synset VALUES ('n#09924164',' volume ',NULL,'a relative amount; \\\\"mix one volume of the solution with ten volumes of water\\\\"');
INSERT INTO english_synset VALUES ('n#09924294',' capacity content ',NULL,'the amount that can be contained; \\\\"the gas tank has a capacity of 12 gallons\\\\"');
INSERT INTO english_synset VALUES ('n#09924436',' population ',NULL,'the number of inhabitants in a given place (country or city etc.); \\\\"people come and go, but the population of this town has remained approximately constant for the past decade\\\\"');
INSERT INTO english_synset VALUES ('n#09924669',' proof ',NULL,'a measure of alcoholic strength expressed as an integer twice the percentage of alcohol present (by volume)');
INSERT INTO english_synset VALUES ('n#09924828',' relations dealings ',NULL,'mutual dealings or connections or communications among persons or groups');
INSERT INTO english_synset VALUES ('n#09924967',' causality ',NULL,'the relation between causes and effects');
INSERT INTO english_synset VALUES ('n#09925062',' relationship human_relationship ',NULL,'(`relationship'' is often used where `relation'' would serve (as in \\\\"the relationship between inflation and unemployment\\\\")) preferred usage of `relationship'' is for human relations or states of relatedness; \\\\"the relationship between mothers and children\\\\"');
INSERT INTO english_synset VALUES ('n#09925412',' function ',NULL,'a relation such that one thing is dependent on another; \\\\"height is a function of age\\\\"; \\\\"price is a function of supply and demand\\\\"');
INSERT INTO english_synset VALUES ('n#09925596',' personal_relation personal_relationship ',NULL,'a relation between persons');
INSERT INTO english_synset VALUES ('n#09925728',' bonding ',NULL,'a close personal relationship that forms between people (as between husband and wife or parent and child)');
INSERT INTO english_synset VALUES ('n#09925941',' female_bonding ',NULL,'the formation of a close personal relationship between women');
INSERT INTO english_synset VALUES ('n#09926062',' male_bonding ',NULL,'the formation of a close personal relationship between men; \\\\"the rituals known as male bonding do not necessarily involve drinking beer together\\\\"');
INSERT INTO english_synset VALUES ('n#09926266',' maternal-infant_bonding ',NULL,'the attachment that forms between an infant and its mother beginning at birth; \\\\"maternal-infant bonding influences the child''s psychological and physical development\\\\"');
INSERT INTO english_synset VALUES ('n#09926502',' logical_relation ',NULL,'a relation between logical propositions');
INSERT INTO english_synset VALUES ('n#09926676',' mathematical_relation ',NULL,'a relation between mathematical expressions (such as equality or inequality)');
INSERT INTO english_synset VALUES ('n#09926856',' function mathematical_function ',NULL,'a mathematical relation such that each element of one set is associated with at least one element of another set');
INSERT INTO english_synset VALUES ('n#09927173',' inverse_function ',NULL,'the function obtained by expressing the dependent variable of one function as the independent variable of another; f and g are inverse functions if f(x)=y and g(y)=x');
INSERT INTO english_synset VALUES ('n#09927401',' transformation ',NULL,'a function that changes the position or direction of the axes of a coordinate system');
INSERT INTO english_synset VALUES ('n#09927564',' affine_transformation ',NULL,'a transformation that is a combination of single transformations such as translation or rotation or reflection on an axis');
INSERT INTO english_synset VALUES ('n#09927753',' mapping map correspondence ',NULL,'a function such that for every element of one set there is a unique element of another set');
INSERT INTO english_synset VALUES ('n#09927920',' operator ',NULL,'(mathematics) a symbol that represents a function from functions to functions; \\\\"the integral operator\\\\"');
INSERT INTO english_synset VALUES ('n#09928113',' linear_operator ',NULL,'an operator that obeys the distributive law: A(f+g) = Af + Ag (where f and g are function)');
INSERT INTO english_synset VALUES ('n#09928265',' identity identity_element identity_operator ',NULL,'an operator that leaves unchanged the element on which it operates; \\\\"the identity under numerical multiplication is 1\\\\"');
INSERT INTO english_synset VALUES ('n#09928477',' trigonometric_function circular_function ',NULL,'function of an angle expressed as a ratio of the sides of right-angled triangle containing the angle');
INSERT INTO english_synset VALUES ('n#09928774',' sine ',NULL,'ratio of the opposite side to the hypotenuse');
INSERT INTO english_synset VALUES ('n#09928869',' cosine ',NULL,'ratio of the adjacent side to the hypotenuse');
INSERT INTO english_synset VALUES ('n#09928966',' tangent ',NULL,'ratio of the opposite to the adjacent side');
INSERT INTO english_synset VALUES ('n#09929062',' cotangent ',NULL,'ratio of the adjacent to the opposite side');
INSERT INTO english_synset VALUES ('n#09929160',' secant ',NULL,'ratio of the hypotenuse to the adjacent side');
INSERT INTO english_synset VALUES ('n#09929257',' cosecant ',NULL,'ratio of the hypotenuse to the opposite side');
INSERT INTO english_synset VALUES ('n#09929356',' threshold_function ',NULL,'a function that takes the value 1 if a specified function of the arguments exceeds a given threshold and 0 otherwise');
INSERT INTO english_synset VALUES ('n#09929537',' exponential exponential_function ',NULL,'a function in which an independent variable appears as an exponent');
INSERT INTO english_synset VALUES ('n#09929684',' exponential_equation ',NULL,'an equation involving exponential functions of a variable');
INSERT INTO english_synset VALUES ('n#09929808',' exponential_curve ',NULL,'a graph of an exponential function');
INSERT INTO english_synset VALUES ('n#09929906',' exponential_expression ',NULL,'a mathematical expression consisting of the constant e raised to some power');
INSERT INTO english_synset VALUES ('n#09930050',' exponential_series ',NULL,'a series derived from the expansion of an exponential expression');
INSERT INTO english_synset VALUES ('n#09930179',' parity ',NULL,'(mathematics) a relation between a pair of integers: if both integers are odd or both are even they have the same parity; if one is odd and the other is even they have different parity');
INSERT INTO english_synset VALUES ('n#09930416',' foundation ',NULL,'the basis on which something is grounded; \\\\"there is little foundation for his objections\\\\"');
INSERT INTO english_synset VALUES ('n#09930598',' footing basis ground ',NULL,'a relation that provides the foundation for something; \\\\"they were on a friendly footing\\\\" or \\\\"he worked on an interim basis\\\\"');
INSERT INTO english_synset VALUES ('n#09930810',' common_ground ',NULL,'a basis agreed to by all parties for reaching a mutual understanding');
INSERT INTO english_synset VALUES ('n#09930938',' grass_roots ',NULL,'the essential foundation or source; \\\\"the problem was attacked at the grass roots\\\\"');
INSERT INTO english_synset VALUES ('n#09931077',' connection connexion connectedness ',NULL,'a relation between things or events (as in the case of one causing the other or sharing features with it); \\\\"there was a connection between eating that pickle and having that nightmare\\\\"');
INSERT INTO english_synset VALUES ('n#09931544',' alliance bond ',NULL,'a connection based on kinship or marriage or common interest: \\\\"the shifting alliances within a large family\\\\"; \\\\"their friendship constitutes a powerful bond between them\\\\"');
INSERT INTO english_synset VALUES ('n#09931775',' linkage ',NULL,'an associative relation');
INSERT INTO english_synset VALUES ('n#09931870',' link nexus ',NULL,'the means of connection between things linked in series');
INSERT INTO english_synset VALUES ('n#09931984',' communication ',NULL,'a connection allowing access between persons or places; \\\\"how many lines of communication can there be among four people?\\\\"; \\\\"a secret passageway provided communication between the two rooms\\\\"');
INSERT INTO english_synset VALUES ('n#09932233',' concatenation ',NULL,'the linking together of a consecutive series of symbols or events or ideas etc; \\\\"it was cause by an improbable concatenation of circumstances\\\\"');
INSERT INTO english_synset VALUES ('n#09932435',' bridge ',NULL,'something resembling a bridge in form or function: \\\\"his letters provided a bridge across the centuries\\\\"');
INSERT INTO english_synset VALUES ('n#09932591',' involvement ',NULL,'a connection of inclusion or containment; \\\\"he escaped involvement in the accident\\\\"; \\\\"there was additional involvement of the liver and spleen\\\\"');
INSERT INTO english_synset VALUES ('n#09932827',' implication ',NULL,'a relation implicated by virtue of involvement or close connection (especially an incriminating involvement); \\\\"he was suspected of implication in several robberies\\\\"');
INSERT INTO english_synset VALUES ('n#09933049',' inclusion comprehension ',NULL,'the relation of comprising something; \\\\"he admired the inclusion of so many ideas in such a short work\\\\"');
INSERT INTO english_synset VALUES ('n#09933223',' unconnectedness ',NULL,'the lack of a connection between things');
INSERT INTO english_synset VALUES ('n#09933378',' relevance relevancy ',NULL,'the relation of something to the matter at hand');
INSERT INTO english_synset VALUES ('n#09933601',' materiality ',NULL,'relevance requiring careful consideration');
INSERT INTO english_synset VALUES ('n#09933718',' cogency ',NULL,'persuasive relevance');
