INSERT INTO english_synset VALUES ('n#09933949',' germaneness ',NULL,'pertinence by virtue of a close relation to the matter at hand');
INSERT INTO english_synset VALUES ('n#09934069',' reference_to regard_to relation_to respect_to ',NULL,'(usually preceded by `with'') relation of delimitation; \\\\"he inquired with respect to the address\\\\"');
