INSERT INTO english_synset VALUES ('n#09935083',' immateriality ',NULL,'complete irrelevance requiring no further consideration');
INSERT INTO english_synset VALUES ('n#09935216',' unrelatedness ',NULL,'the lack of any particular manner of connectedness');
INSERT INTO english_synset VALUES ('n#09935362',' extraneousness ',NULL,'unrelatedness by virtue of falling outside the matter at hand');
INSERT INTO english_synset VALUES ('n#09935484',' grammatical_relation ',NULL,'a linguistic relation established by grammar');
INSERT INTO english_synset VALUES ('n#09935847',' linguistic_relation ',NULL,'a relation between linguistic forms or constituents');
INSERT INTO english_synset VALUES ('n#09936000',' agreement concord ',NULL,'the determination of grammatical inflection on the basis of word relations');
INSERT INTO english_synset VALUES ('n#09936212',' number_agreement ',NULL,'agreement in number between words in the same grammatical construction (e.g., between adjectives and the nouns they modify)');
INSERT INTO english_synset VALUES ('n#09936398',' person_agreement ',NULL,'agreement in person between pronouns and verbs');
INSERT INTO english_synset VALUES ('n#09936507',' case_agreement ',NULL,'agreement in grammatical case between words in the same construction');
INSERT INTO english_synset VALUES ('n#09936636',' gender_agreement ',NULL,'agreement in grammatical gender between words in the same construction');
INSERT INTO english_synset VALUES ('n#09936769',' transitivity transitiveness ',NULL,'the grammatical relation created by a transitive verb');
INSERT INTO english_synset VALUES ('n#09936916',' intransitivity intransitiveness ',NULL,'the grammatical relation created by an intransitive verb');
INSERT INTO english_synset VALUES ('n#09937070',' coreference ',NULL,'the grammatical relation between two words that have a common referent');
INSERT INTO english_synset VALUES ('n#09937216',' reflexivity reflexiveness ',NULL,'the coreferential relation between a reflexive pronoun and its antecedent');
INSERT INTO english_synset VALUES ('n#09937363',' conjunction ',NULL,'the grammatical relation between linguistic units (words or phrases or clauses) that are connected by a conjunction');
