INSERT INTO english_synset VALUES ('n#09938238',' adversative_conjunction ',NULL,'the conjunctive relation of units that expresses the opposition of their meanings');
INSERT INTO english_synset VALUES ('n#09938389',' complementation ',NULL,'the grammatical relation of a word or phrase to a predicate');
INSERT INTO english_synset VALUES ('n#09938510',' coordination ',NULL,'the grammatical relation of two constituents having the same grammatical form');
INSERT INTO english_synset VALUES ('n#09938646',' subordination ',NULL,'the grammatical relation of a modifying word or phrase to its head');
INSERT INTO english_synset VALUES ('n#09938772',' modification qualifying limiting ',NULL,'the grammatical relation that exists when a word qualifies the meaning of the phrase');
