INSERT INTO english_synset VALUES ('n#09939137',' apposition ',NULL,'a grammatical relation between a word and a noun phrase that follows; \\\\"`Rudolph the red-nosed reindeer'' is an example of apposition\\\\"');
INSERT INTO english_synset VALUES ('n#09939326',' mood mode modality ',NULL,'verb inflections that express how the action or state is conceived by the speaker');
INSERT INTO english_synset VALUES ('n#09939566',' indicative_mood indicative declarative_mood declarative common_mood fact_mood ',NULL,'a mood (grammatically unmarked) that represents the act or state as an objective fact');
INSERT INTO english_synset VALUES ('n#09939785',' subjunctive_mood subjunctive ',NULL,'a mood that represent an act or state (not as a fact but) as contingent or possible');
INSERT INTO english_synset VALUES ('n#09939945',' optative_mood optative ',NULL,'a mood (as in Greek or Sanskrit) that expresses a wish or hope; expressed in English by modal verbs');
INSERT INTO english_synset VALUES ('n#09940115',' imperative_mood imperative jussive_mood ',NULL,'a mood that expresses an intention to influence the listener''s behavior');
