INSERT INTO english_synset VALUES ('n#09940425',' modality mode ',NULL,'a classification of propositions on the basis of whether they claim necessity or possibility or impossibility');
INSERT INTO english_synset VALUES ('n#09940596',' anaphoric_relation ',NULL,'the relation between an anaphor and its antecedent');
