INSERT INTO english_synset VALUES ('n#09941109',' passive_voice passive ',NULL,'the voice used to indicate that the subject of the verb is the recipient (not the source) of the action denoted by the verb');
INSERT INTO english_synset VALUES ('n#09941320',' inflection inflexion ',NULL,'a change in the form of a word (usually by adding a suffix) to indicate a change in its grammatical function');
INSERT INTO english_synset VALUES ('n#09941551',' conjugation ',NULL,'the inflection of verbs');
