INSERT INTO english_synset VALUES ('n#09941778',' paradigm ',NULL,'systematic arrangement of all the inflected forms of a word');
INSERT INTO english_synset VALUES ('n#09941892',' aspect ',NULL,'the beginning or duration or completion or repetition of the action of a verb');
