INSERT INTO english_synset VALUES ('n#09942653',' inchoative_aspect ',NULL,'aspect with regard to the beginning of the action of the verb');
INSERT INTO english_synset VALUES ('n#09942778',' progressive progressive_tense imperfect imperfect_tense continuous_tense ',NULL,'a tense of verbs used in describing action that is on-going');
INSERT INTO english_synset VALUES ('n#09943018',' present_progressive present_progressive_tense ',NULL,'a tense used to express action that is on-going at the time of utterance');
INSERT INTO english_synset VALUES ('n#09943184',' perfective perfective_tense perfect perfect_tense ',NULL,'a tense of verbs used in describing action that has been completed (sometimes regarded as perfective aspect)');
INSERT INTO english_synset VALUES ('n#09943448',' present_perfect present_perfect_tense ',NULL,'a perfective tense used to express action completed in the present; \\\\"`I have finished'' is an example of the present perfect\\\\"');
