INSERT INTO english_synset VALUES ('n#09943779',' past_perfect past_perfect_tense pluperfect pluferfect_tense ',NULL,'a perfective tense used to express action completed in the past; \\\\"`Ihad finished'' is an example of the past perfect\\\\"');
