INSERT INTO english_synset VALUES ('n#09944221',' future_perfect future_perfect_tense ',NULL,'a perfective tense used to describe action that will be completed in the future; \\\\"`I will have finished'' is an example of the future perfect\\\\"');
INSERT INTO english_synset VALUES ('n#09944446',' future_progressive future_progressive_tense ',NULL,'a progressive tense used to express action that will be on-going in the future; \\\\"`I will be running'' is an example of the future progressive\\\\"');
INSERT INTO english_synset VALUES ('n#09944679',' semantic_relation ',NULL,'a relation between meanings');
