INSERT INTO english_synset VALUES ('n#09946775',' unit ',NULL,'an individual or group or structure or other entity regarded as a structural or functional constituent of a whole; \\\\"the reduced the number of units and installations\\\\"; \\\\"the word is a basic linguistic unit\\\\"');
INSERT INTO english_synset VALUES ('n#09947031',' member ',NULL,'anything that belongs to a set or class: \\\\"snakes are members of the class Reptilia\\\\"; \\\\"members of the opposite sex\\\\"');
INSERT INTO english_synset VALUES ('n#09947198',' substance ',NULL,'the stuff of which an object consists');
INSERT INTO english_synset VALUES ('n#09947291',' remainder residual residue residuum rest ',NULL,'something left after other parts have been taken away; \\\\"there was no remainder\\\\"; \\\\"he threw away the rest\\\\"');
INSERT INTO english_synset VALUES ('n#09947509',' leftover remnant ',NULL,'a small part or portion that remains after the main part no longer exists');
INSERT INTO english_synset VALUES ('n#09947647',' subpart ',NULL,'a part of a part');
INSERT INTO english_synset VALUES ('n#09947717',' affinity kinship ',NULL,'a close connection marked by community of interests or similarity in nature or character: \\\\"found a natural affinity with the immigrants\\\\"; \\\\"felt a deep kinship with the other students\\\\"; \\\\"anthropology''s kinship with the humanities\\\\"');
INSERT INTO english_synset VALUES ('n#09948047',' rapport ',NULL,'relation of mutual understanding or trust between people');
INSERT INTO english_synset VALUES ('n#09948157',' sympathy ',NULL,'a relation of affinity or harmony between people; whatever affects one correspondingly affects the other; \\\\"the two of them were in close sympathy\\\\"');
INSERT INTO english_synset VALUES ('n#09948376',' mutual_understanding mutual_affection ',NULL,'sympathy of each person for the other');
INSERT INTO english_synset VALUES ('n#09948499',' affinity phylogenetic_relation ',NULL,'(biology) state of relationship between organisms or groups of organisms resulting in resemblance in structure or structural parts: \\\\"in anatomical structure prehistoric man shows close affinity with modern humans\\\\"');
INSERT INTO english_synset VALUES ('n#09948791',' kinship family_relationship relationship ',NULL,'state of relatedness or connection by blood or marriage or adoption');
INSERT INTO english_synset VALUES ('n#09949111',' descent line_of_descent lineage filiation ',NULL,'the kinship relation between an individual and the individual''s progenitors');
INSERT INTO english_synset VALUES ('n#09949316',' affinity kinship_by_marriage ',NULL,'kinship by marriage or adoption; not a blood relationship');
INSERT INTO english_synset VALUES ('n#09949486',' steprelationship ',NULL,'a family relationship by virtue of remarriage');
INSERT INTO english_synset VALUES ('n#09949594',' consanguinity blood_kinship cognation ',NULL,'related by blood');
INSERT INTO english_synset VALUES ('n#09949716',' parentage birth ',NULL,'the kinship relation of an offspring to the parents');
INSERT INTO english_synset VALUES ('n#09949831',' fatherhood paternity ',NULL,'the kinship relation between an offspring and the father');
INSERT INTO english_synset VALUES ('n#09949956',' motherhood maternity ',NULL,'the kinship relation between an offspring and the mother');
INSERT INTO english_synset VALUES ('n#09950081',' sisterhood sistership ',NULL,'the kinship relation between a female offspring and the siblings');
INSERT INTO english_synset VALUES ('n#09950234',' brotherhood ',NULL,'the kinship relation between a male offspring and the siblings');
INSERT INTO english_synset VALUES ('n#09950354',' bilateral_descent ',NULL,'line of descent traced through both the maternal and paternal sides of the family');
INSERT INTO english_synset VALUES ('n#09950499',' unilateral_descent ',NULL,'line of descent traced through one side of the family');
INSERT INTO english_synset VALUES ('n#09950653',' matrilineage enation cognation ',NULL,'line of descent traced through the maternal side of the family');
INSERT INTO english_synset VALUES ('n#09950796',' patrilineage agnation ',NULL,'line of descent traced through the paternal side of the family');
INSERT INTO english_synset VALUES ('n#09950928',' magnitude_relation ',NULL,'a relation between magnitudes');
