INSERT INTO english_synset VALUES ('n#09951183',' proportion proportionality ',NULL,'the quotient obtained when the magnitude of a part is divided by the magnitude of the whole');
INSERT INTO english_synset VALUES ('n#09951476',' content ',NULL,'the proportion of a substance that is contained in a mixture or alloy etc.');
INSERT INTO english_synset VALUES ('n#09951604',' scale ',NULL,'the ratio between the size of something and a representation of it; \\\\"the scale of the map\\\\"; \\\\"the scale of the model\\\\"');
INSERT INTO english_synset VALUES ('n#09951772',' golden_section golden_mean ',NULL,'the proportional relation between two divisions of line or two dimension of a plane figure such that short : long :: long : (short + long)');
INSERT INTO english_synset VALUES ('n#09951985',' commensurateness correspondence proportionateness ',NULL,'the relation of correspondence in degree or size or amount');
INSERT INTO english_synset VALUES ('n#09952143',' percentage percent per_centum pct ',NULL,'a proportion multiplied by 100');
INSERT INTO english_synset VALUES ('n#09952367',' absentee_rate ',NULL,'the percentage of workers who do not report to work');
INSERT INTO english_synset VALUES ('n#09952478',' batting_average ',NULL,'(baseball) the percentage of times a batter gets a hit; number of base hits divided by the number of times at bat');
