INSERT INTO english_synset VALUES ('n#09954230',' aspect_ratio ',NULL,'the ratio of the width to the height of a tv picture');
INSERT INTO english_synset VALUES ('n#09954341',' cephalic_index breadth_index cranial_index ',NULL,'ratio (in percent) of the maximum breadth to the maximum length of a skull');
INSERT INTO english_synset VALUES ('n#09954508',' efficiency ',NULL,'the ratio of the output to the input of any system');
