INSERT INTO english_synset VALUES ('n#10471669',' chelate chelate_compound ',NULL,'a heterocyclic compound having a metal ion attached by coordinate bonds to at least two nonmetal ions');
INSERT INTO english_synset VALUES ('n#10471843',' atom ',NULL,'(physics and chemistry) the smallest component of an element having the chemical properties of the element');
