INSERT INTO english_synset VALUES ('n#10475185',' noble_gas inert_gas argonon ',NULL,'any of the chemically inert gaseous elements of the helium group (group 8A or 0 of the periodic table)');
INSERT INTO english_synset VALUES ('n#10475491',' helium_group ',NULL,'the series of inert gases');
