INSERT INTO english_synset VALUES ('n#10478256',' aluminum aluminium Al atomic_number_13 ',NULL,'a silvery ductile metallic element found primarily in bauxite');
INSERT INTO english_synset VALUES ('n#10478501',' alum potassium_alum potash_alum ',NULL,'a white crystalline double sulfate of aluminum: the potassium double sulfate of aluminum');
INSERT INTO english_synset VALUES ('n#10478671',' alum ammonia_alum ammonium_alum ',NULL,'a white crystalline double sulfate of aluminum: the ammonium double sulfate of aluminum');
INSERT INTO english_synset VALUES ('n#10478840',' americium Am atomic_number_95 ',NULL,'a radioactive transuranic metallic element; discovered by bombarding uranium with helium atoms');
INSERT INTO english_synset VALUES ('n#10479014',' antimony Sb atomic_number_51 ',NULL,'a metallic element having four allotropic forms; used in a wide variety of alloys; found in stibnite');
INSERT INTO english_synset VALUES ('n#10479212',' argon Ar atomic_number_18 ',NULL,'a colorless and odorless inert gas; one of the six inert gases; comprises approximately 1% of the earth''s atmosphere');
INSERT INTO english_synset VALUES ('n#10479441',' arsenic As atomic_number_33 ',NULL,'a very poisonous metallic element that has three allotropic forms; arsenic and arsenic compounds are used as herbicides and insecticides and various alloys; found in arsenopyrite and orpiment and realgar');
