INSERT INTO english_synset VALUES ('n#10481113',' bismuth Bi atomic_number_83 ',NULL,'a heavy brittle diamagnetic trivalent metallic element (resembles arsenic and antimony chemically); usually recovered as a by-product from ores of other metals');
