INSERT INTO english_synset VALUES ('n#10482489',' carbon C atomic_number_6 ',NULL,'an abundant nonmetallic tetravalent element occurring in three allotropic forms: amorphous carbon and graphite and diamond; occurs in all organic compounds');
INSERT INTO english_synset VALUES ('n#10482884',' carbon_atom ',NULL,'an atom of carbon');
INSERT INTO english_synset VALUES ('n#10482959',' radiocarbon carbon_14 ',NULL,'a radioactive isotope of carbon');
INSERT INTO english_synset VALUES ('n#10483060',' cerium Ce atomic_number_58 ',NULL,'a ductile gray metallic element of the lanthanide series; used in lighter flints; the most abundant of the rare-earth group');
