INSERT INTO english_synset VALUES ('n#10483561',' cesium_137 ',NULL,'a radioactive isotope of cesium used in radiation therapy');
INSERT INTO english_synset VALUES ('n#10483675',' chlorine Cl atomic_number_17 ',NULL,'a common nonmetallic element belonging to the halogens; best known as a heavy yellow irritating toxic gas; used to purify water and as a bleaching agent and disinfectant; occurs naturally only as a salt (as in sea water)');
