INSERT INTO english_synset VALUES ('n#10484122',' chromium Cr atomic_number_24 ',NULL,'a hard brittle blue-white multivalent metallic element; resistant to corrosion and tarnishing');
INSERT INTO english_synset VALUES ('n#10484331',' cobalt Co atomic_number_27 ',NULL,'a hard ferromagnetic silver-white bivalent or trivalent metallic element; a trace element in plant and animal nutrition');
INSERT INTO english_synset VALUES ('n#10484583',' cobalt_60 ',NULL,'a radioactive isotope of cobalt with mass number 60; a source of exceptionally intense gamma rays; used in radiation therapy');
INSERT INTO english_synset VALUES ('n#10484763',' copper Cu atomic_number_29 ',NULL,'a ductile malleable reddish-brown corrosion-resistant diamagnetic metallic element; occurs in various minerals but is the only metal that occurs abundantly in large masses; used as an electrical and thermal conductor');
