INSERT INTO english_synset VALUES ('n#10486257',' fluorine F atomic_number_9 ',NULL,'a nonmetallic univalent element; usually a yellow irritating toxic flammable gas; a powerful oxidizing agent; recovered from fluorite or cryolite or fluorapatite');
