INSERT INTO english_synset VALUES ('n#10486747',' gadolinium Gd atomic_number_64 ',NULL,'a ductile silvery-white ductile ferromagnetic trivalent metallic element of the rare earth group');
INSERT INTO english_synset VALUES ('n#10486962',' gallium Ga atomic_number_31 ',NULL,'a rare silvery (usually trivalent) metallic element; brittle at low temperatures but liquid above room temperature; occurs in trace amounts in bauxite and zinc ores');
