INSERT INTO english_synset VALUES ('n#10487939',' hafnium Hf atomic_number_72 ',NULL,'a gray tetravalent metallic element that resembles zirconium chemically and is found in zirconium minerals; used in filaments for its ready emission of electrons');
INSERT INTO english_synset VALUES ('n#10488178',' helium He atomic_number_2 ',NULL,'a very light colorless element that is one of the six inert gasses; the most difficult gas to liquefy; occurs in economically extractable amounts in certain natural gases (as those found in Texas and Kansas)');
INSERT INTO english_synset VALUES ('n#10488479',' holmium Ho atomic_number_67 ',NULL,'a trivalent metallic element of the rare earth group; occurs together with yttrium; forms highly magnetic compounds');
INSERT INTO english_synset VALUES ('n#10488691',' hydrogen H atomic_number_1 ',NULL,'a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and lightest and most abundant element in the universe');
