INSERT INTO english_synset VALUES ('n#10490965',' lead Pb atomic_number_82 ',NULL,'a soft heavy toxic malleable metallic element; bluish white when freshly cut but tarnishes readily to dull gray; \\\\"the children were playing with lead soldiers\\\\"');
