INSERT INTO english_synset VALUES ('n#10491747',' magnesium Mg atomic_number_12 ',NULL,'a light silver-white ductile bivalent metallic element; in pure form it burns with brilliant white flame; occurs naturally only in combination (as in magnesite and dolomite and carnallite and spinel and olivine)');
INSERT INTO english_synset VALUES ('n#10492152',' manganese Mn atomic_number_25 ',NULL,'a hard brittle gray polyvalent metallic element that resembles iron but is not magnetic; used in making steel; occurs in many minerals');
INSERT INTO english_synset VALUES ('n#10492461',' mendelevium Md Mv atomic_number_101 ',NULL,'a radioactive transuranic element synthesized by bombarding einsteinium with alpha particles');
INSERT INTO english_synset VALUES ('n#10492641',' mercury quicksilver Hg atomic_number_80 ',NULL,'a heavy silvery toxic univalent and bivalent metallic element; the only metal that is liquid at ordinary temperatures');
INSERT INTO english_synset VALUES ('n#10492888',' molybdenum Mo atomic_number_42 ',NULL,'a polyvalent metallic element that resembles chromium and tungsten in its properties; used to strengthen and harden steel');
INSERT INTO english_synset VALUES ('n#10493109',' neodymium Nd atomic_number_60 ',NULL,'a yellow trivalent metallic element of the rare earth group; occurs in monazite and bastnasite in association with cerium and lanthanum and praseodymium');
INSERT INTO english_synset VALUES ('n#10493379',' neon Ne atomic_number_10 ',NULL,'a colorless odorless gaseous element that give a red glow in a vacuum tube; one of the six inert gasses; occurs in the air in small amounts');
