INSERT INTO english_synset VALUES ('n#10494444',' nitrogen N atomic_number_7 ',NULL,'a common nonmetallic element that is normally a colorless odorless tasteless inert diatomic gas; constitutes 78 percent of the atmosphere by volume; a constituent of all living tissues');
