INSERT INTO english_synset VALUES ('n#10496811',' plutonium Pu atomic_number_94 ',NULL,'a radioactive transuranic element that is similar to uranium; found in minute quantities in uranium ores but is usually synthesized in nuclear reactors; 13 isotopes are known with the most important being plutonium 239');
