INSERT INTO english_synset VALUES ('n#10497338',' polonium Po atomic_number_84 ',NULL,'a radioactive metallic_element that is similar to tellurium and bismuth; occurs in uranium ores but can be produced by bombarding bismuth with neutrons in a nuclear reactor');
