INSERT INTO english_synset VALUES ('n#10498490',' protactinium protoactinium Pa atomic_number_91 ',NULL,'a short-lived radioactive metallic element formed from uranium and disintegrating into actinium and then into lead');
INSERT INTO english_synset VALUES ('n#10498703',' radium Ra atomic_number_88 ',NULL,'an intensely radioactive metallic element that occurs in minute amounts in uranium ores');
INSERT INTO english_synset VALUES ('n#10498886',' radon Rn atomic_number_86 ',NULL,'a radioactive gaseous element formed by the disintegration of radium; the heaviest of the inert gasses; occurs naturally (especially in areas over granite) and is considered a hazard to health');
