INSERT INTO english_synset VALUES ('n#10499405',' rhodium Rh atomic_number_45 ',NULL,'a white hard metallic element that is one of the platinum group and is found in platinum ores; used in alloys with platinum');
INSERT INTO english_synset VALUES ('n#10499606',' rubidium Rb atomic_number_37 ',NULL,'a soft silvery metallic element of the alkali metal group; burns in air and reacts violently in water; occurs in carnallite and lepidolite and pollucite');
INSERT INTO english_synset VALUES ('n#10499894',' ruthenium Ru atomic_number_44 ',NULL,'a rare polyvalent metallic element of the platinum group; it is found associated with platinum');
INSERT INTO english_synset VALUES ('n#10500068',' rutherfordium Rf kurchatovium Ku unnilquadium Unq element_104 atomic_number_104 ',NULL,'a radioactive transuranic element which has been synthesized');
INSERT INTO english_synset VALUES ('n#10500268',' samarium Sm atomic_number_62 ',NULL,'a gray lustrous metallic element of the rare earth group; is used in special alloys; occurs in monazite and bastnasite');
INSERT INTO english_synset VALUES ('n#10500503',' scandium Sc atomic_number_21 ',NULL,'a white trivalent metallic element; sometimes classified in the rare earth group; occurs in the Scandinavian mineral thortveitite');
INSERT INTO english_synset VALUES ('n#10500730',' selenium Se atomic_number_34 ',NULL,'a toxic nonmetallic element related to sulfur and tellurium; occurs in several allotropic forms; a stable gray metallike allotrope conducts electricity better in the light than in the dark and is used in photocells; occurs in sulfide ores (as pyrite)');
INSERT INTO english_synset VALUES ('n#10501078',' silicon Si atomic_number_14 ',NULL,'a tetravalent nonmetallic element; next to oxygen it is the most abundant element in the earth''s crust; occurs in clay and feldspar and granite and quartz and sand; used as a semiconductor in transistors');
