INSERT INTO english_synset VALUES ('n#10501854',' sodium Na atomic_number_11 ',NULL,'a silvery soft waxy metallic element of the alkali metal group; occurs abundantly in natural compounds (especially in salt water); burns with a yellow flame and reacts violently in water; occurs in sea water and in the mineral halite (rock salt)');
INSERT INTO english_synset VALUES ('n#10502214',' strontium Sr atomic_number_38 ',NULL,'a soft silver-white or yellowish metallic element of the alkali metal group; turns yellow in air; occurs in celestite and strontianite');
INSERT INTO english_synset VALUES ('n#10502485',' strontium_90 ',NULL,'a radioactive isotope of strontium (with the mass number 90) that is present in the fallout from nuclear explosions; can be assimilated like calcium into bones');
INSERT INTO english_synset VALUES ('n#10502703',' sulfur S sulphur atomic_number_16 ',NULL,'an abundant tasteless odorless multivalent nonmetallic element; best known in yellow crystals; occurs in many sulphide and sulphate minerals and even in native form (especially in volcanic regions)');
INSERT INTO english_synset VALUES ('n#10503042',' tantalum Ta atomic_number_73 ',NULL,'a hard gray lustrous metallic element that is highly corrosion-resistant; occurs in niobite and fergusonite and tantalite');
INSERT INTO english_synset VALUES ('n#10503299',' technetium Tc atomic_number_43 ',NULL,'a crystalline metallic element not found in nature; occurs as one of the fission products of uranium');
INSERT INTO english_synset VALUES ('n#10503480',' tellurium Te atomic_number_52 ',NULL,'a brittle silver-white metalloid element that is related to selenium and sulfur; it is used in alloys and as a semiconductor; occurs mainly as tellurides in ores of copper and nickel and silver and gold');
INSERT INTO english_synset VALUES ('n#10503800',' terbium Tb atomic_number_65 ',NULL,'a metallic element of the rare earth group; used in lasers; occurs in apatite and monazite and xenotime and ytterbite');
INSERT INTO english_synset VALUES ('n#10504052',' thallium Tl atomic_number_81 ',NULL,'a soft gray malleable metallic element that resembles tin but discolors on exposure to air; it is highly toxic and is used in rodent and insect poisons; occurs in zinc blende and some iron ores');
INSERT INTO english_synset VALUES ('n#10504343',' thorium Th atomic_number_90 ',NULL,'a soft silvery-white tetravalent radioactive metallic element; isotope 232 is used as a power source in nuclear reactors; occurs in thorite and in monazite sands');
