INSERT INTO english_synset VALUES ('n#10504929',' tin Sn atomic_number_50 ',NULL,'a silvery malleable metallic element that resists corrosion; used in many alloys and to coat other metals to prevent corrosion; obtained chiefly from cassiterite where it occurs as tin oxide');
INSERT INTO english_synset VALUES ('n#10505231',' titanium Ti atomic_number_22 ',NULL,'a light strong gray lustrous corrosion-resistant metallic element used in strong light-weight alloys (as for airplane parts); the main sources are rutile and ilmenite');
INSERT INTO english_synset VALUES ('n#10505514',' tungsten wolfram W atomic_number_74 ',NULL,'a heavy gray-white metallic element; the pure form is used mainly in electrical applications; it is found in several ores including wolframite and scheelite');
INSERT INTO english_synset VALUES ('n#10505796',' unnilhexium Unh element_106 atomic_number_106 ',NULL,'a transuranic element');
INSERT INTO english_synset VALUES ('n#10505915',' unnilquintium unnilpentium Unp hahnium element_105 atomic_number_105 ',NULL,'a transuranic element that has not been found in nature');
INSERT INTO english_synset VALUES ('n#10506095',' unnilseptium Uns element_107 atomic_number_107 ',NULL,'a transuranic element that has not been found in nature');
INSERT INTO english_synset VALUES ('n#10506249',' uranium U atomic_number_92 ',NULL,'a heavy toxic silvery-white radioactive metallic element; occurs in many isotopes; used for nuclear fuels and nuclear weapons');
INSERT INTO english_synset VALUES ('n#10506506',' uranium_235 ',NULL,'a uranium isotope with mass number 235; capable of sustaining chain reactions');
INSERT INTO english_synset VALUES ('n#10506641',' uranium_238 ',NULL,'the commonest isotope of uranium; it is not fissionable but when irradiated with neutrons it produces fissionable plutonium 239');
INSERT INTO english_synset VALUES ('n#10506826',' vanadium V atomic_number_23 ',NULL,'a soft silvery white toxic metallic element used in steel alloys; it occurs in several complex minerals including carnotite and vanadinite');
INSERT INTO english_synset VALUES ('n#10507080',' xenon Xe atomic_number_54 ',NULL,'a colorless odorless inert gaseous element occurring in the earth''s atmosphere in trace amounts');
INSERT INTO english_synset VALUES ('n#10507288',' ytterbium Yb atomic_number_70 ',NULL,'a soft silvery metallic element; a rare earth of the lanthanide series; it occurs in gadolinite and monazite and xenotime');
INSERT INTO english_synset VALUES ('n#10507546',' yttrium Y atomic_number_39 ',NULL,'a silvery metallic element that is common in rare-earth minerals; used in magnesium and aluminum alloys');
INSERT INTO english_synset VALUES ('n#10507783',' zinc Zn atomic_number_30 ',NULL,'a bluish-white lustrous metallic element; brittle at ordinary temperatures but malleable when heated; used in a wide variety of alloys and in galvanizing iron; it occurs as zinc sulphide in zinc blende');
