INSERT INTO english_synset VALUES ('r#00017131',' rather kind_of kinda sort_of ',NULL,'to some (great or small) extent; \\\\"it was rather cold\\\\"; \\\\"the party was rather nice\\\\"; \\\\"the knife is rather dull\\\\"; \\\\"I rather regret that I cannot attend\\\\"; \\\\"He''s rather good at playing the cello\\\\"; \\\\"he is kind of shy\\\\"');
INSERT INTO english_synset VALUES ('r#00017406',' pretty jolly ',NULL,'intensifier, as in \\\\"pretty big\\\\"; \\\\"pretty bad\\\\"; (`jolly'' is used informally in Britain as in \\\\"jolly decent of him\\\\")');
INSERT INTO english_synset VALUES ('r#00017563',' quite ',NULL,'to the greatest extent; completely; \\\\"you''re quite right\\\\"; \\\\"she was quite alone\\\\"; \\\\"was quite mistaken\\\\"; \\\\"quite the opposite\\\\"; \\\\"not quite finished\\\\"; \\\\"did not quite make it\\\\"');
INSERT INTO english_synset VALUES ('r#00017767',' quite rather ',NULL,'to a degree (not used with a negative); \\\\"quite tasty\\\\"; \\\\"quite soon\\\\"; \\\\"quite ill\\\\"; \\\\"quite rich\\\\"');
INSERT INTO english_synset VALUES ('r#00017904',' quite quite_a quite_an ',NULL,'of an unusually noticeable or exceptional or remarkable kind (not used with a negative); \\\\"her victory was quite something\\\\"; \\\\"she''s quite a girl\\\\"; \\\\"quite a film\\\\"; \\\\"quite a walk\\\\"; \\\\"we''ve had quite an afternoon\\\\"');
INSERT INTO english_synset VALUES ('r#00018167',' quite ',NULL,'actually or truly or to an extreme; \\\\"was quite a sudden change\\\\"; \\\\"it''s quite the thing to do\\\\"; \\\\"quite the rage\\\\"; \\\\"Quite so!\\\\"');
INSERT INTO english_synset VALUES ('r#00018325',' always ever e''er ',NULL,'at all times; all the time and on every occasion; \\\\"I will always be there to help you\\\\"; \\\\"always arrives on time\\\\"; \\\\"there is always some pollution in the air\\\\"; \\\\"ever hoping to strike it rich\\\\"; \\\\"ever busy\\\\"');
INSERT INTO english_synset VALUES ('r#00018595',' always ',NULL,'forever; throughout all time; \\\\"we will always be friends\\\\"; \\\\"I shall treasure it always\\\\"; \\\\"I will always love you\\\\"');
INSERT INTO english_synset VALUES ('r#00018743',' always ',NULL,'at any time or in any event; \\\\"you can always resign if you don''t like it\\\\"; \\\\"you could always take a day off\\\\"');
INSERT INTO english_synset VALUES ('r#00018886',' always forever ',NULL,'seemingly without interruption; often and repeatedly; \\\\"always looking for faults\\\\"; \\\\"it is always raining\\\\"; \\\\"he is forever cracking jokes\\\\"; \\\\"they are forever arguing\\\\"');
INSERT INTO english_synset VALUES ('r#00019096',' constantly ',NULL,'without interruption; \\\\"the world is constantly changing\\\\"');
INSERT INTO english_synset VALUES ('r#00019209',' constantly perpetually ',NULL,'seemingly uninterrupted; \\\\"constantly bullied by his big brother\\\\"; \\\\"was perpetually answering the doorbell\\\\"');
INSERT INTO english_synset VALUES ('r#00019404',' constantly ',NULL,'without variation or change; \\\\"constantly kind and gracious\\\\"');
INSERT INTO english_synset VALUES ('r#00019520',' never ne''er ',NULL,'not ever; at no time in the past or future; \\\\"I have never been to China\\\\"; \\\\"I shall never forget this day\\\\"; \\\\"had never seen a circus\\\\"; \\\\"never on Sunday\\\\"; \\\\"I will never marry you!\\\\"');
INSERT INTO english_synset VALUES ('r#00019758',' never ',NULL,'not at all; certainly not; not in any circumstances; \\\\"never fear\\\\"; \\\\"bringing up children is never easy\\\\"; \\\\"that will never do\\\\"; \\\\"what is morally wrong can never be politically right\\\\"');
INSERT INTO english_synset VALUES ('r#00019973',' ways n-ways ',NULL,'n is between 2 and infinity; \\\\"They split the loot four ways\\\\"');
INSERT INTO english_synset VALUES ('r#00020075',' occasionally on_occasion once_in_a_while now_and_then now_and_again at_times from_time_to_time ',NULL,'now and then or here and there; \\\\"he was arrogant and occasionally callous\\\\"; \\\\"open areas are only occasionally interrupted by clumps of trees\\\\"; \\\\"they visit New York on occasion\\\\"; \\\\"now and again she would take her favorite book from the shelf and read to us\\\\"; \\\\"as we drove along, the beautiful scenery now and then attracted his attention\\\\"');
INSERT INTO english_synset VALUES ('r#00020565',' sometime ',NULL,'at some indefinite or unstated time; \\\\"let''s get together sometime\\\\"; \\\\"everything has to end sometime\\\\"; \\\\"It was to be printed sometime later\\\\"');
INSERT INTO english_synset VALUES ('r#00020741',' sometimes ',NULL,'on certain occasions or in certain cases but not always; \\\\"sometimes she wished she were back in England\\\\"; \\\\"sometimes her photography is breathtaking\\\\"; \\\\"sometimes they come for a month; at other times for six months\\\\"');
INSERT INTO english_synset VALUES ('r#00020994',' equally as every_bit ',NULL,'(often followed by `as'') to the same degree; \\\\"they were equally beautiful\\\\"; \\\\"birds were singing and the child sang as sweetly\\\\"; \\\\"sang as sweetly as a nightingale\\\\"; (`every bit'' is informal as in \\\\"he is every bit as mean as she is\\\\")');
INSERT INTO english_synset VALUES ('r#00021296',' long_ago long_since lang_syne ',NULL,'of the distant or comparatively distant past; \\\\"We met once long ago\\\\"; \\\\"they long ago forsook their nomadic life\\\\"; \\\\"left for work long ago\\\\"; \\\\"he has long since given up mountain climbing\\\\"; \\\\"This name has long since been forgotten\\\\"; \\\\"lang syne\\\\" is Scottish');
INSERT INTO english_synset VALUES ('r#00021612',' pretty_much ',NULL,'to some degree; \\\\"we were pretty much lost when we met the forest ranger\\\\"');
INSERT INTO english_synset VALUES ('r#00021724',' much practically ',NULL,'(degree adverb used before a noun phrase) for all practical purposes but not completely; \\\\"much the same thing happened every time\\\\"');
INSERT INTO english_synset VALUES ('r#00021901',' that_much ',NULL,'to a certain degree; \\\\"we will be that much ahead of them\\\\"');
INSERT INTO english_synset VALUES ('r#00021996',' palmately ',NULL,'in a palmate manner; \\\\"palmately cleft\\\\"');
INSERT INTO english_synset VALUES ('r#00022090',' paradoxically ',NULL,'in a paradoxical manner; \\\\"paradoxically, ice ages seem to occur when the sun gets hotter\\\\"');
INSERT INTO english_synset VALUES ('r#00022239',' parasitically ',NULL,'in a parasitic manner');
INSERT INTO english_synset VALUES ('r#00022320',' conventionally ',NULL,'in a conventional manner; \\\\"he usually behaves rather conventionally\\\\"');
INSERT INTO english_synset VALUES ('r#00022467',' unconventionally ',NULL,'in an unconventional manner; \\\\"she always behaves rather unconventionally\\\\"');
INSERT INTO english_synset VALUES ('r#00022621',' pathogenically ',NULL,'in a pathogenic manner');
INSERT INTO english_synset VALUES ('r#00022704',' pictorially ',NULL,'in a pictorial manner; \\\\"depth is established pictorially\\\\"');
INSERT INTO english_synset VALUES ('r#00022819',' not ',NULL,'negation of a word or group of words; \\\\"he does not speak French\\\\"; \\\\"she is not going\\\\"; \\\\"they are not friends\\\\"; \\\\"not many\\\\"; \\\\"not much\\\\"; \\\\"not at all\\\\"');
INSERT INTO english_synset VALUES ('r#00022997',' n''t ',NULL,'contraction of `not''; combining form; \\\\"isn''t\\\\"');
INSERT INTO english_synset VALUES ('r#00023074',' no ',NULL,'used to express refusal or denial or disagreement etc or especially to emphasize a negative statement; \\\\"no, you are wrong\\\\"');
INSERT INTO english_synset VALUES ('r#00023227',' any ',NULL,'to any degree or extent; \\\\"it isn''t any better\\\\"');
INSERT INTO english_synset VALUES ('r#00023305',' no ',NULL,'not in any degree or manner; not at all; \\\\"he is no better today\\\\"');
INSERT INTO english_synset VALUES ('r#00023400',' none ',NULL,'not at all or in no way; \\\\"seemed none too pleased with his dinner\\\\"; \\\\"shirt looked none the worse for having been slept in\\\\"; \\\\"none too prosperous\\\\"; \\\\"the passage is none too clear\\\\"');
INSERT INTO english_synset VALUES ('r#00023611',' neither ',NULL,'after a negative statement used to indicate that the next statement is similarly negative; \\\\"I was not happy and neither were they\\\\"; \\\\"just as you would not complain, neither should he\\\\"');
INSERT INTO english_synset VALUES ('r#00023830',' either ',NULL,'after a negative statement used as an intensive meaning something like `likewise'' or `also''; \\\\"he isn''t stupid, but he isn''t exactly a genius either\\\\"; \\\\"I don''t know either\\\\"; \\\\"if you don''t order dessert I won''t either\\\\"');
INSERT INTO english_synset VALUES ('r#00024081',' not_only ',NULL,'(used to introduce the first phrase of a correlative construction and usually followed by `but'') \\\\"not only was he poor, but...\\\\"');
INSERT INTO english_synset VALUES ('r#00024245',' bloody damn all-fired ',NULL,'(intensifier) \\\\"you are bloody right\\\\"; \\\\"Why are you so all-fired aggressive?\\\\"');
INSERT INTO english_synset VALUES ('r#00024375',' anywhere anyplace ',NULL,'at or in or to any place; \\\\"you can find this food anywhere\\\\"; (`anyplace'' is used informally for `anywhere'')');
INSERT INTO english_synset VALUES ('r#00024530',' nowhere ',NULL,'not anywhere; in or at or to no place; \\\\"I am going nowhere\\\\"');
INSERT INTO english_synset VALUES ('r#00024625',' somewhere someplace ',NULL,'in or at or to some place; \\\\"she must be somewhere\\\\"; (`someplace'' is used informally for `somewhere'')');
INSERT INTO english_synset VALUES ('r#00024775',' everywhere everyplace all_over ',NULL,'to or in any or all places; \\\\"You find fast food stores everywhere\\\\"; \\\\"people everywhere are becoming aware of the problem\\\\"; \\\\"he carried a gun everywhere he went\\\\"; \\\\"looked all over for a suitable gift\\\\"; (`everyplace'' is used informally for `everywhere'')');
INSERT INTO english_synset VALUES ('r#00025089',' high_and_low ',NULL,'everywhere; \\\\"searched high and low\\\\"');
INSERT INTO english_synset VALUES ('r#00025165',' somehow someway someways in_some_way in_some_manner ',NULL,'in some unspecified way or manner; or by some unspecified means; \\\\"they managed somehow\\\\"; \\\\"he expected somehow to discover a woman who would love him\\\\"; \\\\"he tried to make is someway acceptable\\\\"');
INSERT INTO english_synset VALUES ('r#00025444',' somehow for_some_reason ',NULL,'for some unspecified reason; \\\\"It doesn''t seem fair somehow\\\\"; \\\\"he had me dead to rights but somehow I got away with it\\\\"; \\\\"for some reason they didn''t seem to match\\\\"');
INSERT INTO english_synset VALUES ('r#00025661',' anyhow anyway in_any_case at_any_rate in_any_event ',NULL,'used to indicate that a statement explains or supports a previous statement; \\\\"Anyhow, he is dead now\\\\"; \\\\"I think they''re asleep; anyhow, they''re quiet\\\\"; \\\\"I don''t know what happened to it; anyway, it''s gone\\\\"; \\\\"anyway, there is another factor to consider\\\\"; \\\\"I don''t know how it started; in any case, there was a brief scuffle\\\\"; \\\\"in any event, the government faced a serious protest\\\\"; \\\\"but at any rate he got a knighthood for it\\\\"');
INSERT INTO english_synset VALUES ('r#00026173',' as_it_is ',NULL,'in the actual state of affairs and often contrary to expectations; \\\\"he might have been killed; as it is he was severely injured\\\\"');
INSERT INTO english_synset VALUES ('r#00026338',' anyhow anyway ',NULL,'in any way whatsoever; \\\\"they came anyhow they could\\\\"; \\\\"get it done anyway you can\\\\"');
INSERT INTO english_synset VALUES ('r#00026464',' however nevertheless withal still yet all_the_same even_so nonetheless notwithstanding ',NULL,'despite anything to the contrary (usually following a concession); \\\\"although I''m a little afraid, however I''d like to try it\\\\"; \\\\"while we disliked each other, nevertheless we agreed\\\\"; \\\\"he was a stern yet fair master\\\\"; \\\\"granted that it is dangerous, all the same I still want to go\\\\"');
INSERT INTO english_synset VALUES ('r#00026875',' yet ',NULL,'up to the present time; \\\\"I have yet to see the results\\\\"; \\\\"details are yet to be worked out\\\\"');
INSERT INTO english_synset VALUES ('r#00026998',' so_far thus_far up_to_now hitherto heretofore as_yet yet til_now until_now ',NULL,'used in negative statement to describe a situation that has existed up to this point or up to the present time; \\\\"So far he hasn''t called\\\\"; \\\\"the sun isn''t up yet\\\\"');
INSERT INTO english_synset VALUES ('r#00027278',' so_far yet ',NULL,'used after a superlative; \\\\"this is the best so far\\\\"; \\\\"the largest drug bust yet\\\\"');
INSERT INTO english_synset VALUES ('r#00027399',' only ',NULL,'except that; \\\\"It was the same story; only this time she came out better\\\\"');
INSERT INTO english_synset VALUES ('r#00027504',' however ',NULL,'in whatever way or manner; \\\\"Victory, however it was brought about, was sweet\\\\"; \\\\"however he did it, it was very clever\\\\"');
INSERT INTO english_synset VALUES ('r#00027658',' however ',NULL,'to whatever degree or extent; \\\\"The results, however general, are important\\\\"; \\\\"they have begun, however reluctantly, to acknowledge the legitimacy of some of the opposition''s concerns\\\\"');
INSERT INTO english_synset VALUES ('r#00027877',' however ',NULL,'by contrast; on the other hand; \\\\"the first part was easy; the second, however, took hours\\\\"');
INSERT INTO english_synset VALUES ('r#00028003',' lightly ',NULL,'with indifference or without dejection; \\\\"he took it lightly\\\\"');
INSERT INTO english_synset VALUES ('r#00028117',' besides in_any_case ',NULL,'making an additional point; anyway; \\\\"I don''t want to go to a restaurant; besides, we can''t afford it\\\\"; \\\\"she couldn''t shelter behind him all the time and in any case he wasn''t always with her\\\\"');
INSERT INTO english_synset VALUES ('r#00028358',' fugally ',NULL,'(music) in a fugal style');
INSERT INTO english_synset VALUES ('r#00028436',' furthermore moreover what_is_more ',NULL,'in addition; \\\\"computer chess games are getting cheaper all the time; furthermore, their quality is improving\\\\"; \\\\"the cellar was dark; moreover, mice nested there\\\\"; \\\\"what is more, there''s no sign of a change\\\\"');
INSERT INTO english_synset VALUES ('r#00028708',' farther further ',NULL,'to or at a greater distance in time or space (`farther'' is used more frequently than `further'' in this physical sense); \\\\"farther north\\\\"; \\\\"moved farther away\\\\"; \\\\"farther down the corridor\\\\"; \\\\"the practice may go back still farther to the Druids\\\\"; \\\\"went only three miles further\\\\"; \\\\"further in the future\\\\"');
INSERT INTO english_synset VALUES ('r#00029054',' further farther ',NULL,'to or at a greater extent or degree or a more advanced stage (`further'' is used more often than `farther'' in this abstract sense); \\\\"further complicated by uncertainty about the future\\\\"; \\\\"let''s not discuss it further\\\\"; \\\\"nothing could be further from the truth\\\\"; \\\\"they are further along in their research than we expected\\\\"; \\\\"the application of the law was extended farther\\\\"; \\\\"he is going no farther in his studies\\\\"');
INSERT INTO english_synset VALUES ('r#00029512',' further ',NULL,'in addition or furthermore; \\\\"if we further suppose\\\\"; \\\\"stated further that he would not cooperate with them\\\\"; \\\\"they are definitely coming; further, they should be here already\\\\"');
INSERT INTO english_synset VALUES ('r#00029723',' farthest furthest ',NULL,'to the greatest distance in space or time (`farthest'' is used more often than `furthest'' in this physical sense); \\\\"see who could jump the farthest\\\\"; \\\\"chose the farthese seat from the door\\\\"; \\\\"he swam the furthest\\\\"');
INSERT INTO english_synset VALUES ('r#00029983',' furthest farthest ',NULL,'to the greatest degree or extent or most advanced stage (`furthest'' is used more often than `farthest'' in this abstract sense); \\\\"went the furthest of all the children in her education\\\\"; \\\\"furthest removed from reality\\\\"; \\\\"she goes farthest in helping us\\\\"');
INSERT INTO english_synset VALUES ('r#00030283',' futilely ',NULL,'in a futile and unproductive manner');
INSERT INTO english_synset VALUES ('r#00030373',' still ',NULL,'with reference to action or condition; without change, interruption, or cessation; \\\\"it''s still warm outside\\\\"; \\\\"will you still love me when we''re old and grey?\\\\"');
INSERT INTO english_synset VALUES ('r#00030584',' no_longer no_more ',NULL,'not now; \\\\"she is no more\\\\"');
INSERT INTO english_synset VALUES ('r#00030675',' anymore any_longer ',NULL,'at the present or from now on; usually used with a negative; \\\\"Alice doesn''t live here anymore\\\\"; \\\\"the children promised not to quarrel any more\\\\"');
INSERT INTO english_synset VALUES ('r#00030867',' already ',NULL,'prior to a specified or implied time; \\\\"she has already graduated\\\\"');
INSERT INTO english_synset VALUES ('r#00030986',' not_yet ',NULL,'subsequent to a specified or implied time; \\\\"he hasn''t arrived yet\\\\"');
INSERT INTO english_synset VALUES ('r#00031106',' very really real rattling ',NULL,'intensifiers; \\\\"she was very gifted\\\\"; \\\\"he played very well\\\\"; \\\\"a really enjoyable evening\\\\"; (`real'' is sometimes used informally for `really'' as in \\\\"I''m real sorry about it\\\\"; `rattling'' is informal as in \\\\"a rattling good yarn\\\\")');
INSERT INTO english_synset VALUES ('r#00031391',' mighty powerful right ',NULL,'(Southern regional intensive) very; \\\\"the baby is mighty cute\\\\"; \\\\"he''s mighty tired\\\\"; \\\\"it is powerful humid\\\\"; \\\\"that boy is powerful big now\\\\"; \\\\"they have a right nice place\\\\"');
INSERT INTO english_synset VALUES ('r#00031615',' good_and ',NULL,'(informal) completely or thoroughly; \\\\"when I''m good and ready\\\\"');
INSERT INTO english_synset VALUES ('r#00031714',' fucking ',NULL,'intensifier, very colloquial; \\\\"what took you so fucking long?\\\\"');
INSERT INTO english_synset VALUES ('r#00031812',' much ',NULL,'very; \\\\"he was much annoyed\\\\"');
INSERT INTO english_synset VALUES ('r#00031872',' henceforth henceforward ',NULL,'from this time forth; from now on; \\\\"henceforth she will be known as Mrs. Smith\\\\"');
INSERT INTO english_synset VALUES ('r#00032005',' hereafter ',NULL,'following this in time or order or place; after this; \\\\"hereafter you will no longer receive an allowance\\\\"');
INSERT INTO english_synset VALUES ('r#00032148',' hereafter ',NULL,'in a future life or state; \\\\"hope to win salvation hereafter\\\\"');
INSERT INTO english_synset VALUES ('r#00032246',' just just_now ',NULL,'only a moment ago; \\\\"he has just arrived\\\\"; \\\\"the sun just now came out\\\\"');
INSERT INTO english_synset VALUES ('r#00032359',' instantaneously outright instantly in_a_flash ',NULL,'without any delay; \\\\"he was killed outright\\\\"');
INSERT INTO english_synset VALUES ('r#00032500',' mightily ',NULL,'to a great degree; \\\\"rejoiced mightily at the news\\\\"');
INSERT INTO english_synset VALUES ('r#00032587',' mildly ',NULL,'to a moderate degree; \\\\"he was mildly interested\\\\"');
INSERT INTO english_synset VALUES ('r#00032688',' a_bit a_little a_trifle ',NULL,'to a small degree; somewhat; \\\\"it''s a bit warm\\\\"; \\\\"felt a little better\\\\"; \\\\"a trifle smaller\\\\"');
INSERT INTO english_synset VALUES ('r#00032834',' anon ',NULL,'(old-fashioned or informal) in a little while; \\\\"see you anon\\\\"');
INSERT INTO english_synset VALUES ('r#00032928',' soon shortly presently before_long ',NULL,'in the near future; \\\\"the doctor will soon be here\\\\"; \\\\"the book will appear shortly\\\\"; \\\\"she will arrive presently\\\\"; \\\\"we should have news before long\\\\"');
INSERT INTO english_synset VALUES ('r#00033143',' shortly not_long ',NULL,'for a short time; \\\\"he was at the airport shortly before she was expected to arrive\\\\"');
INSERT INTO english_synset VALUES ('r#00033273',' shortly not_far ',NULL,'at a short distance; \\\\"the hem fell shortly below her knees\\\\"');
INSERT INTO english_synset VALUES ('r#00033378',' momentarily in_a_moment momently ',NULL,'at any moment; \\\\"she will be with you momently\\\\"');
INSERT INTO english_synset VALUES ('r#00033489',' shoulder-to-shoulder ',NULL,'side by side and close together; \\\\"the troops marched shoulder-to-shoulder\\\\"');
INSERT INTO english_synset VALUES ('r#00033630',' soonest earliest ',NULL,'with the least delay; \\\\"the soonest I can arrive is 3 P.M.\\\\"');
INSERT INTO english_synset VALUES ('r#00033735',' sportively ',NULL,'in a merry sportive manner');
INSERT INTO english_synset VALUES ('r#00033818',' stormily turbulently passionately ',NULL,'in a stormy or violent manner');
INSERT INTO english_synset VALUES ('r#00033931',' frequently often oftentimes oft ofttimes ',NULL,'many times at short intervals; \\\\"we often met over a cup of coffee\\\\"');
INSERT INTO english_synset VALUES ('r#00034128',' oftener ',NULL,'more often or more frequently');
INSERT INTO english_synset VALUES ('r#00034193',' anon ',NULL,'at another time; \\\\"ever and anon\\\\"');
INSERT INTO english_synset VALUES ('r#00034258',' rarely seldom ',NULL,'not often; \\\\"we rarely met\\\\"');
INSERT INTO english_synset VALUES ('r#00034364',' curiously oddly peculiarly ',NULL,'in a manner differing from the usual or expected; \\\\"had a curiously husky voice\\\\"; \\\\"he''s behaving rather peculiarly\\\\"');
INSERT INTO english_synset VALUES ('r#00034591',' curiously_enough funnily_enough interestingly_enough oddly_enough strangely_enough ',NULL,'curious (or funny or interesting or odd or strange) though it may seem; \\\\"curiously enough, he didn''t recognize his old friend\\\\"; \\\\"interestingly enough, America is now dependent on Africa for a large part of its oil\\\\"; \\\\"funnily enough, the ones I thought so ugly were the ones that sold out first\\\\"; \\\\"oddly enough, he hasn''t mentioned it\\\\"');
INSERT INTO english_synset VALUES ('r#00035044',' strangely ',NULL,'in a strange way; \\\\"he was strangely silent\\\\"');
INSERT INTO english_synset VALUES ('r#00035125',' reasonably moderately within_reason somewhat fairly middling passably ',NULL,'to a moderately sufficient extent or degree; \\\\"the shoes are priced reasonably\\\\"; \\\\"he is fairly clever with computers\\\\"; \\\\"they lived comfortably within reason\\\\"');
INSERT INTO english_synset VALUES ('r#00035463',' unreasonably immoderately ',NULL,'to a degree that exceeds the bounds or reason or moderation; \\\\"his prices are unreasonably high\\\\"');
INSERT INTO english_synset VALUES ('r#00035686',' slightly somewhat ',NULL,'to a small degree or extent; \\\\"his arguments were somewhat self-contradictory\\\\"; \\\\"the children argued because one slice of cake was slightly larger than the other\\\\"');
INSERT INTO english_synset VALUES ('r#00035913',' movingly ',NULL,'in a moving manner; \\\\"she sang movingly\\\\"');
INSERT INTO english_synset VALUES ('r#00036007',' extensively ',NULL,'to a great extent');
INSERT INTO english_synset VALUES ('r#00036082',' extensively ',NULL,'in a widespread way; \\\\"oxidation ponds are extensively used for sewage treatment in the Midwest\\\\"');
INSERT INTO english_synset VALUES ('r#00036235',' intrinsically per_se as_such in_and_of_itself ',NULL,'with respect to its inherent nature; \\\\"this statement is interesting per se\\\\"');
INSERT INTO english_synset VALUES ('r#00036408',' decidedly unquestionably emphatically definitely by_all_odds ',NULL,'without question and beyond doubt; \\\\"it was decidedly too expensive\\\\"; \\\\"by all odds they should win\\\\"');
INSERT INTO english_synset VALUES ('r#00036639',' truly genuinely really ',NULL,'in accordance with truth or fact or reality; \\\\"she was now truly American\\\\"; \\\\"a genuinely open society\\\\"; \\\\"they don''t really listen to us\\\\"');
INSERT INTO english_synset VALUES ('r#00036883',' indeed ',NULL,'(used as an interjection to express surprise or skepticism or irony etc.) \\\\"Wants to marry the butler? Indeed!\\\\"');
INSERT INTO english_synset VALUES ('r#00037028',' indeed so ',NULL,'in truth (often tends to intensify); \\\\"they said the car would break down and indeed it did\\\\"; \\\\"it is very cold indeed\\\\"; \\\\"was indeed grateful\\\\"; \\\\"indeed, the rain may still come\\\\"; \\\\"he did so do it!\\\\"');
INSERT INTO english_synset VALUES ('r#00037263',' in_truth really truly forsooth ',NULL,'(used as intensifiers or sentence modifiers) \\\\"in truth, moral decay hastened the decline of the Roman Empire\\\\"; \\\\"really, you shouldn''t have done it\\\\"; \\\\"a truly awful book\\\\"; (`forsooth'' is archaic and now usually used to express disbelief)');
INSERT INTO english_synset VALUES ('r#00037564',' naturally of_course course ',NULL,'as might be expected; \\\\"naturally, the lawyer sent us a huge bill\\\\"');
INSERT INTO english_synset VALUES ('r#00037706',' unnaturally ',NULL,'not as might be expected; \\\\"The early Church not unnaturally adopted the position that failure to see the messianic character of his work was really caused by the people''s own blindness\\\\"');
INSERT INTO english_synset VALUES ('r#00037949',' clearly ',NULL,'without doubt or question; \\\\"they were clearly lost\\\\"; \\\\"history has clearly shown the folly of that policy\\\\"');
INSERT INTO english_synset VALUES ('r#00038108',' obviously evidently manifestly patently apparently plainly plain ',NULL,'unmistakably; \\\\"the answer is obviously wrong\\\\"; \\\\"she was in bed and evidently in great pain\\\\"; \\\\"he was manifestly too important to leave off the guest list\\\\"; \\\\"it is all patently nonsense\\\\"; \\\\"she has apparently been living here for some time\\\\"; \\\\"I thought he owned the property, but apparently not\\\\"; \\\\"You are plainly wrong\\\\"; (`plain'' is often used informally for `plainly'' as in \\\\"he is plain stubborn\\\\")');
INSERT INTO english_synset VALUES ('r#00038718',' apparently seemingly ostensibly on_the_face_of_it ',NULL,'from appearances alone; \\\\"irrigation often produces bumper crops from apparently desert land\\\\"; \\\\"the child is seemingly healthy but the doctor is concerned\\\\"; \\\\"had been ostensibly frank as to his purpose while really concealing it\\\\"-Thomas Hardy; \\\\"on the face of it the problem seems minor\\\\"');
INSERT INTO english_synset VALUES ('r#00039142',' again once_again once_more over_again ',NULL,'anew; \\\\"she tried again\\\\"; \\\\"they rehearsed the scene again\\\\"');
INSERT INTO english_synset VALUES ('r#00039271',' withal ',NULL,'together with this');
INSERT INTO english_synset VALUES ('r#00039324',' by_chance accidentally circumstantially unexpectedly ',NULL,'without advance planning; \\\\"they met accidentally\\\\"');
INSERT INTO english_synset VALUES ('r#00039514',' unexpectedly out_of_the_blue ',NULL,'in a way that was not expected; \\\\"her brother showed up at the wedding out of the blue\\\\"');
INSERT INTO english_synset VALUES ('r#00039677',' specifically ',NULL,'in distinction from others; \\\\"a program specifically for teenagers\\\\"; \\\\"he is interested specifically in poisonous snakes\\\\"');
INSERT INTO english_synset VALUES ('r#00039873',' generally in_general in_the_main ',NULL,'without distinction of one from others; \\\\"he is interested in snakes in general\\\\"');
INSERT INTO english_synset VALUES ('r#00040053',' nonspecifically ',NULL,'without specificity; \\\\"nonspecifically staining substances\\\\"');
INSERT INTO english_synset VALUES ('r#00040173',' fortunately fortuitously luckily as_luck_would_have_it ',NULL,'by good fortune; \\\\"fortunately the weather was good\\\\"');
INSERT INTO english_synset VALUES ('r#00040403',' happily ',NULL,'in an unexpectedly lucky way; \\\\"happily he was not injured\\\\"');
INSERT INTO english_synset VALUES ('r#00040533',' sadly unhappily ',NULL,'in an unfortunate way; \\\\"sadly he died before he could see his grandchild\\\\"');
INSERT INTO english_synset VALUES ('r#00040688',' unfortunately unluckily regrettably alas ',NULL,'by bad luck; \\\\"unfortunately it rained all day\\\\"; \\\\"alas, I cannot stay\\\\"');
INSERT INTO english_synset VALUES ('r#00040922',' therefore hence thence thus ',NULL,'(used to introduce a logical conclusion) from that fact or reason or as a result; \\\\"therefore X must be true\\\\"; \\\\"the eggs were fresh and hence satisfactory\\\\"; \\\\"we were young and thence optimistic\\\\"; \\\\"it is late and thus we must go\\\\"; \\\\"the witness is biased and so cannot be trusted\\\\"');
INSERT INTO english_synset VALUES ('r#00041261',' ergo ',NULL,'(used as a sentenced connector) therefore or consequently');
INSERT INTO english_synset VALUES ('r#00041351',' hence ',NULL,'from this time; \\\\"a year hence it will be forgotten\\\\"');
INSERT INTO english_synset VALUES ('r#00041436',' hence ',NULL,'(archaic) from this place; \\\\"get thee hence!\\\\"');
INSERT INTO english_synset VALUES ('r#00041514',' thence therefrom ',NULL,'from that place or from there; \\\\"proceeded thence directly to college\\\\"; \\\\"flew to Helsinki and thence to Moscow\\\\"; \\\\"roads that lead therefrom\\\\"');
INSERT INTO english_synset VALUES ('r#00041700',' thence therefrom thereof ',NULL,'from that circumstance or source; \\\\"atomic formulas and all compounds thence constructible\\\\"- W.V.Quine; \\\\"a natural conclusion follows thence\\\\";\\\\"public interest and a policy deriving therefrom\\\\"; \\\\"Typhus fever results therefrom\\\\"');
